{"content":"#!/usr/bin/env python3
import sys
import os
import re

# Regex for path variable pattern: { followed by alphanumeric, _, - followed by }
VAR_REGEX = re.compile(r'\{[a-zA-Z0-9_-]+\}')
ROLE_REGEX = re.compile(r'^[a-zA-Z0-9_-]+$')

def normalize_path(path):
    return VAR_REGEX.sub('{var}', path)

def get_segments(path):
    return [s for s in path.split('/') if s]

def is_parent_path(parent_norm, child_norm):
    p_segs = get_segments(parent_norm)
    c_segs = get_segments(child_norm)
    return len(p_segs) < len(c_segs) and c_segs[:len(p_segs)] == p_segs

class Endpoint:
    def __init__(self, original_path, norm_path, method, role, permission, index):
        self.original_path = original_path
        self.norm_path = norm_path
        self.method = method            # Uppercase
        self.role = role                # Case-sensitive
        self.permission = permission    # Uppercase
        self.index = index
        self.segment_count = len(get_segments(norm_path))

def parse_input(filepath):
    if not os.path.exists(filepath):
        return [], None, set(), [], {}

    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    lines = [line.strip() for line in content.splitlines()]

    blocks = []
    current_block = []
    for line in lines:
        if not line:
            if current_block:
                blocks.append(current_block)
                current_block = []
        else:
            current_block.append(line)
    if current_block:
        blocks.append(current_block)

    endpoints_block = []
    base_exclude_block = []
    plan_block = []

    if len(blocks) >= 1:
        endpoints_block = blocks[0]

    if len(blocks) == 2:
        first_line = blocks[1][0]
        tokens = first_line.split()
        if tokens and tokens[0].lower() in ('base', 'exclude'):
            base_exclude_block = blocks[1]
        else:
            plan_block = blocks[1]
    elif len(blocks) >= 3:
        base_exclude_block = blocks[1]
        plan_block = blocks[2]

    # 1. Parse ENDPOINTS section with hard cutoff
    endpoints = []
    seen_tuples = set()
    norm_path_to_first_orig = {}

    for index, line in enumerate(endpoints_block):
        tokens = line.split()
        if len(tokens) != 4:
            break  # Hard cutoff
        path, method, role, perm = tokens[0], tokens[1], tokens[2], tokens[3]
        if not path or not role:
            break  # Hard cutoff
        method_upper = method.upper()
        if method_upper not in {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}:
            break  # Hard cutoff
        perm_upper = perm.upper()
        if perm_upper not in {'ALLOW', 'DENY'}:
            break  # Hard cutoff
        if not ROLE_REGEX.match(role):
            break  # Hard cutoff

        norm_p = normalize_path(path)
        if norm_p not in norm_path_to_first_orig:
            norm_path_to_first_orig[norm_p] = path

        tuple_key = (norm_p, method_upper, role)
        if tuple_key in seen_tuples:
            # Rule 3: Deduplication (keep first encountered)
            continue
        seen_tuples.add(tuple_key)

        ep = Endpoint(
            original_path=path,
            norm_path=norm_p,
            method=method_upper,
            role=role,
            permission=perm_upper,
            index=index
        )
        endpoints.append(ep)

    # 2. Parse BASE/EXCLUDE section
    base_path = None
    excluded_roles = set()
    for line in base_exclude_block:
        tokens = line.split()
        if not tokens:
            continue
        cmd = tokens[0].lower()
        if cmd == 'base':
            if len(tokens) > 1:
                base_path = tokens[1]
        elif cmd == 'exclude':
            excluded_roles.update(tokens[1:])

    # 3. Parse PLAN section with hard cutoff
    plan_items = []
    for line in plan_block:
        tokens = line.split()
        if len(tokens) != 2:
            break  # Hard cutoff in PLAN
        p, m = tokens[0], tokens[1]
        if not p:
            break  # Hard cutoff in PLAN
        m_upper = m.upper()
        if m_upper not in {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}:
            break  # Hard cutoff in PLAN
        plan_items.append((normalize_path(p), m_upper))

    return endpoints, base_path, excluded_roles, plan_items, norm_path_to_first_orig


def canonicalize(input_path, output_path):
    endpoints, base_path, excluded_roles, plan_items, norm_path_to_first_orig = parse_input(input_path)

    # Base filter
    norm_base = normalize_path(base_path) if base_path is not None else None
    base_eligible_eps = []
    for ep in endpoints:
        if norm_base is None or ep.norm_path.startswith(norm_base):
            base_eligible_eps.append(ep)

    selected_eps = set()

    if not plan_items:
        # PLAN is empty
        for ep in base_eligible_eps:
            if ep.role not in excluded_roles:
                selected_eps.add(ep)
    else:
        norm_plan_set = set(plan_items)
        target_plan_eps = []

        # Find endpoints in base_eligible_eps matching PLAN
        for ep in base_eligible_eps:
            if (ep.norm_path, ep.method) in norm_plan_set:
                target_plan_eps.append(ep)
                if ep.role not in excluded_roles:
                    selected_eps.add(ep)

        # Parent path resolution for target PLAN endpoints
        for target_ep in target_plan_eps:
            # Find all candidate parent paths in base_eligible_eps
            path_to_eps = {}
            for ep in base_eligible_eps:
                path_to_eps.setdefault(ep.norm_path, []).append(ep)

            for cand_norm_path, eps_at_path in path_to_eps.items():
                if is_parent_path(cand_norm_path, target_ep.norm_path):
                    non_excluded = [ep for ep in eps_at_path if ep.role not in excluded_roles]
                    if non_excluded:
                        # Standard parent path: add non-excluded endpoints
                        selected_eps.update(non_excluded)
                    else:
                        # Special case: all endpoints at parent path have excluded roles
                        # Add them since parent path is needed for inheritance
                        selected_eps.update(eps_at_path)

    if not selected_eps:
        with open(output_path, 'w', encoding='utf-8') as f:
            f.write('\n')
        return

    # Update original path to the first encountered original path for each norm_path
    for ep in selected_eps:
        ep.original_path = norm_path_to_first_orig.get(ep.norm_path, ep.original_path)

    sorted_eps = sorted(
        selected_eps,
        key=lambda ep: (
            -ep.segment_count,
            ep.method,
            ep.role,
            0 if ep.permission == 'ALLOW' else 1,
            ep.original_path
        )
    )

    lines = []
    for ep in sorted_eps:
        lines.append(f"{ep.original_path} {ep.method} {ep.role} {ep.permission}")

    out_text = '\n'.join(lines) + '\n'
    with open(output_path, 'w', encoding='utf-8') as f:
        f.write(out_text)


def main():
    input_file = '/app/input.txt'
    output_file = '/app/output.txt'
    if len(sys.argv) > 1:
        input_file = sys.argv[1]
    if len(sys.argv) > 2:
        output_file = sys.argv[2]

    canonicalize(input_file, output_file)

if __name__ == '__main__':
    main()
